// ❌ 单边映射，漏掉「单词多对一」反向冲突
class Solution {
    public boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (words.length != pattern.length()) return false;
        Map<Character, String> map = new HashMap<>();
        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            String w = words[i];
            if (!map.containsKey(c)) map.put(c, w);
            else if (!map.get(c).equals(w)) return false;
        }
        return true;
    }
}

class Solution {
    public boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (words.length != pattern.length()) return false;

        int[] p2w = new int[26];          // pattern 字符 -> 单词下标(+1)
        Map<String, Integer> w2p = new HashMap<>(); // 单词 -> pattern 字符下标(+1)
        for (int i = 0; i < pattern.length(); i++) {
            int c = pattern.charAt(i) - 'a';
            String w = words[i];
            int mappedWord = w2p.getOrDefault(w, -1); // 该单词已映射到的位置
            if (p2w[c] == 0 && mappedWord == -1) {
                p2w[c] = i + 1;
                w2p.put(w, i + 1);
            } else if (p2w[c] != i + 1 || mappedWord != i + 1) {
                return false; // 任一边不是指向当前位置 -> 非双射
            }
        }
        return true;
    }
}

class Solution {
    public boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (words.length != pattern.length()) return false;

        Map<Character, Integer> lastP = new HashMap<>();
        Map<String, Integer> lastW = new HashMap<>();
        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            String w = words[i];
            if (lastP.getOrDefault(c, -1) != lastW.getOrDefault(w, -1)) return false;
            lastP.put(c, i);
            lastW.put(w, i);
        }
        return true;
    }
}

