import java.util.*;

class RandomizedSet {
    private List<Integer> list = new ArrayList<>();
    private Map<Integer, Integer> pos = new HashMap<>();
    private Random rand = new Random();

    public RandomizedSet() {}

    public boolean insert(int val) {
        if (pos.containsKey(val)) return false; // 已存在
        pos.put(val, list.size());              // 新元素下标 = 当前长度
        list.add(val);                           // 追加到末尾
        return true;
    }

    public boolean remove(int val) {
        if (!pos.containsKey(val)) return false; // 不存在
        int idx = pos.get(val);                  // val 当前下标
        int last = list.get(list.size() - 1);    // 末尾元素
        list.set(idx, last);                     // 末尾元素填到 idx 位置（覆盖 val）
        pos.put(last, idx);                      // 更新末尾元素的新下标
        list.remove(list.size() - 1);            // 弹出末尾（O(1)）
        pos.remove(val);                         // 删除 val 映射
        return true;
    }

    public int getRandom() {
        return list.get(rand.nextInt(list.size())); // 等概率随机取
    }
}

